def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if not alive_opponents:
        if hp <= 2 or no_water_days >= 2:
            return min(budget, 62.0)
        return min(budget, 24.0)

    prev_bids = []
    desperate_count = 0
    weak_count = 0
    error_count = 0
    for opp in alive_opponents:
        if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 2:
            desperate_count += 1
        if opp.get('hp', 0) <= 4:
            weak_count += 1
        prev = opp.get('previous_trace', {}) or {}
        if prev.get('error'):
            error_count += 1
        bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(bid)
        status = prev.get('status')
        if status in ('failed', 'error', 'dead'):
            error_count += 1

    if hp <= 1:
        base = 68.0
    elif hp <= 2 or no_water_days >= 2:
        base = 63.0
    elif hp <= 4 or no_water_days >= 1:
        base = 49.0
    else:
        base = 34.0

    if supply >= 22:
        base -= 6.0
    elif supply <= 17:
        base += 7.0

    if prev_bids:
        highest_prev = max(prev_bids)
        avg_prev = sum(prev_bids) / float(len(prev_bids))
        if hp <= 2 or no_water_days >= 2:
            target = highest_prev + 2.0
            base = max(base, target)
        else:
            if highest_prev >= 62.0:
                base = min(base, 28.0 if hp >= 5 else 45.0)
            elif avg_prev >= 45.0:
                base = max(base, avg_prev + 1.5)
            else:
                base = max(base, highest_prev + 1.0)

    if desperate_count >= 2:
        base += 6.0
    elif desperate_count == 0 and weak_count >= 1 and hp >= 5:
        base -= 4.0

    if error_count >= 1:
        base -= 3.0

    if day >= 8:
        if hp >= 5 and no_water_days == 0:
            base -= 3.0
        else:
            base += 4.0

    base = max(0.0, min(base, budget))

    if budget < 25.0:
        return min(budget, max(base, budget * 0.9))
    return base

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    hp = int(my_status.get('hp', 0))
    budget = float(my_status.get('budget', 0.0))

    alive_opps = []
    for opp in opponents_status.values():
        if opp.get('alive', False):
            alive_opps.append(opp)

    # Base target: aim to win enough to cover our requirement when supply is near mid/high.
    # Since bids are simultaneous and hidden, we use a heuristic bid fraction.
    # If supply is low, we bid more to avoid losing water.
    supply_norm = 0.0
    if MAX_SUPPLY > MIN_SUPPLY:
        supply_norm = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
    supply_norm = max(0.0, min(1.0, supply_norm))

    # Conservative mid bid that scales with scarcity.
    scarcity = 1.0 - supply_norm
    base_frac = 0.45 + 0.25 * scarcity  # between ~0.45 and ~0.70

    # React to yesterday bids if available.
    prev_bids = []
    for opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    if prev_bids:
        highest_prev_bid = max(prev_bids)
        # If an opponent was bidding near our daily salary, they likely value survival highly.
        if highest_prev_bid >= 0.85 * DAILY_SALARY:
            # Overbid slightly unless we're already in very bad shape.
            if hp > 3:
                frac = min(0.95, base_frac + 0.20)
            else:
                frac = min(1.0, base_frac + 0.35)
        else:
            # Match the pressure just above their max previous bid.
            frac = base_frac
            # Translate their bid magnitude into an additional pressure.
            frac = max(frac, min(0.95, (highest_prev_bid + 5.0) / DAILY_SALARY))
    else:
        frac = base_frac

    # If our HP is low, we must prioritize water allocation.
    if hp <= 2:
        frac = min(1.0, frac + 0.35)
    elif hp <= 3:
        frac = min(0.98, frac + 0.15)

    # Convert fraction to bid, capped by budget.
    bid = frac * DAILY_SALARY
    if bid > budget:
        bid = budget

    # Also cap bid to a reasonable upper bound relative to supply.
    # (Prevents wasting budget when supply is abundant.)
    # We use a soft cap: 1.2 * supply as a proxy.
    soft_cap = max(0.0, 1.2 * supply)
    if bid > soft_cap:
        bid = min(bid, soft_cap)

    # Ensure non-negative.
    if bid < 0.0:
        bid = 0.0

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    supply = int(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    # Determine urgency based on hp and no_water_days
    if hp <= 2 or no_water_days >= 1:
        # Very urgent: need water at almost any cost
        max_bid = min(budget, DAILY_SALARY * 0.95)
        # Lower supply means more competition, so bid higher
        if supply < 20:
            return max_bid
        else:
            return min(max_bid, DAILY_SALARY * 0.7)
    elif hp <= 4 or no_water_days == 1:
        # Moderate urgency
        base_bid = DAILY_SALARY * 0.5
        if supply < 20:
            return min(budget, base_bid + 10)
        else:
            return min(budget, base_bid)
    else:
        # Healthy: conserve money
        base_bid = DAILY_SALARY * 0.35
        if supply < 20:
            return min(budget, base_bid + 5)
        else:
            return min(budget, base_bid)
